package ffdd.opsconsole.treasury.application;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import ffdd.opsconsole.treasury.mapper.SupportCommissionReadMapper;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.LongStream;
import org.apache.ibatis.session.Configuration;
import org.junit.jupiter.api.Test;

class SupportCommissionReadServiceTest {
    @Test void eachActualSourceAndWalletReadFlushesSessionCache(){var c=new Configuration();c.addMapper(SupportCommissionReadMapper.class);for(String method:List.of("fundEvents","fundLedgers","fundWallets","fundTimePrecisions")){var statement=c.getMappedStatement(SupportCommissionReadMapper.class.getName()+"."+method);assertThat(statement.isUseCache()).as(method).isFalse();assertThat(statement.isFlushCacheRequired()).as(method).isTrue();}}
    final SupportCommissionReadMapper mapper=mock(SupportCommissionReadMapper.class);
    final SupportCommissionReadService service=new SupportCommissionReadService(mapper);
    void empty(){when(mapper.fundEvents(anyList())).thenReturn(List.of());when(mapper.fundLedgers(anyList())).thenReturn(List.of());}
    @Test void twoFixedBatchesPreserveBadOriginalsAndImmutableMaps(){empty();var bad=Map.<String,Object>of("customerId",7L,"deleted",1,"userSandbox",1,"status","FAILED");when(mapper.fundEvents(List.of(7L,8L))).thenReturn(List.of(bad));var sources=service.readFundCommissions(List.of(8L,7L,7L));assertThat(sources.events()).containsExactly(bad);verify(mapper,times(1)).fundEvents(List.of(7L,8L));verify(mapper,times(1)).fundLedgers(List.of(7L,8L));assertThatThrownBy(()->sources.events().get(0).put("deleted",0)).isInstanceOf(UnsupportedOperationException.class);}
    @Test void emptyAuthorizedScopeDoesNoQueryAndFailuresAreNeverEmpty(){assertThat(service.readFundCommissions(List.of()).events()).isEmpty();verifyNoInteractions(mapper);empty();when(mapper.fundLedgers(List.of(7L))).thenReturn(null);assertThatThrownBy(()->service.readFundCommissions(List.of(7L))).isInstanceOf(IllegalStateException.class);when(mapper.fundLedgers(List.of(7L))).thenThrow(new IllegalStateException("actual query failure"));assertThatThrownBy(()->service.readFundCommissions(List.of(7L))).hasMessage("actual query failure");}
    @Test void exact4096ScopeAndExactNumericOwnersRejectOverflowFractionAndForeignRows(){empty();service.readFundCommissions(LongStream.rangeClosed(1,4096).boxed().toList());assertThatThrownBy(()->service.readFundCommissions(LongStream.rangeClosed(1,4097).boxed().toList())).isInstanceOf(IllegalArgumentException.class);for(Number owner:List.of(8L,new BigDecimal("7.1"),new BigDecimal("18446744073709551623"))){when(mapper.fundEvents(List.of(7L))).thenReturn(List.of(Map.of("customerId",owner)));assertThatThrownBy(()->service.readFundCommissions(List.of(7L))).isInstanceOf(RuntimeException.class);}assertThatThrownBy(()->service.readFundCommissions(Arrays.asList(7L,null))).isInstanceOf(IllegalArgumentException.class);}
    @Test void boundSqlUsesRealFieldsNoSilentProductionFiltersAndRetainsMalformedPrefixRows(){var c=new Configuration();c.addMapper(SupportCommissionReadMapper.class);for(String method:List.of("fundEvents","fundLedgers")){String sql=c.getMappedStatement(SupportCommissionReadMapper.class.getName()+"."+method).getBoundSql(Map.of("scope",List.of(7L,8L))).getSql();assertThat(sql).contains("? , ?").doesNotContain("is_deleted=0","sandbox=0","source_environment");assertThat(sql.toUpperCase()).doesNotContain("LIMIT","FOR UPDATE");}String ledgers=c.getMappedStatement(SupportCommissionReadMapper.class.getName()+".fundLedgers").getBoundSql(Map.of("scope",List.of(7L))).getSql();assertThat(ledgers).contains("LIKE 'F5-COMMISSION-%'").doesNotContain("REGEXP","DR-REISSUE");String wallet=c.getMappedStatement(SupportCommissionReadMapper.class.getName()+".fundWallets").getBoundSql(Map.of("customer",7L)).getSql();assertThat(wallet).contains("fund_incarnation incarnation","fund_revision revision","w.version","u.sandbox userSandbox","w.sandbox","FOR UPDATE");String metadata=c.getMappedStatement(SupportCommissionReadMapper.class.getName()+".fundTimePrecisions").getBoundSql(Map.of()).getSql();assertThat(metadata).contains("DATETIME_PRECISION","DATABASE()","nx_wallet_ledger","nx_commission_event");}
    @Test void metadataCannotDefaultMissingOrInvalidPrecisionToZero(){var row=Map.<String,Object>of("tableName","nx_wallet_ledger","columnName","created_at","precision",6);when(mapper.fundTimePrecisions()).thenReturn(List.of(row));assertThat(service.timePrecisions()).containsExactly(Map.entry("nx_wallet_ledger.created_at",6));when(mapper.fundTimePrecisions()).thenReturn(List.of());assertThat(service.timePrecisions()).isEmpty();when(mapper.fundTimePrecisions()).thenReturn(List.of(row,row));assertThatThrownBy(service::timePrecisions).isInstanceOf(IllegalStateException.class);for(Object p:List.of(-1,7,"0",new BigDecimal("0.5"))){when(mapper.fundTimePrecisions()).thenReturn(List.of(Map.of("tableName","nx_wallet_ledger","columnName","created_at","precision",p)));assertThatThrownBy(service::timePrecisions).isInstanceOf(RuntimeException.class);}when(mapper.fundTimePrecisions()).thenReturn(null);assertThatThrownBy(service::timePrecisions).isInstanceOf(IllegalStateException.class);}
}
